    if not four_rows:
        return out

    top, bottom = min(four_rows), max(four_rows)
    six_rows = [r for r in range(h) if 6 in grid[r]]
    direction = 1
    if six_rows and min(six_rows) < top:
        direction = -1

    for r in range(h):
        for c in range(w):
            if out[r][c] == 6:
                out[r][c] = 0

    if direction == 1:
        for r in range(top, bottom + 1):
            target = 2 * bottom + 1 - r
            if target < h:
                for c in range(w):
                    if grid[r][c] == 4:
                        out[target][c] = 4
    else:
        for r in range(top, bottom + 1):
            target = 2 * top - 1 - r
            if target >= 0:
                for c in range(w):
                    if grid[r][c] == 4:
                        out[target][c] = 4

